<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';require_login();$pdo=db();if(!table_exists($pdo,'approvals'))redirect('upgrade_phase6.php');$msg=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=post_int('id');$decision=post_string('decision');if(in_array($decision,['approved','rejected'],true)){$pdo->prepare('UPDATE approvals SET status=?,decided_by=?,decision_notes=?,decided_at=NOW() WHERE id=? AND status="pending"')->execute([$decision,current_user()['id'],post_string('decision_notes')?:null,$id]);activity($pdo,'approval','approvals',$id,'Approval decision: '.$decision);flash('success','Approval updated.');}redirect('approvals.php');}
$rows=$pdo->query("SELECT a.*,TRIM(CONCAT(COALESCE(c.first_name,''),' ',COALESCE(c.last_name,''))) client_name FROM approvals a LEFT JOIN clients c ON c.id=a.client_id ORDER BY a.id DESC LIMIT 200")->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Approvals</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;padding:18px 28px;border-bottom:1px solid #e5eaf2}.wrap{max-width:1100px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}.btn{background:#315ee7;color:#fff;border:0;padding:8px 11px;border-radius:7px;font-weight:800}.reject{background:#fff0f0;color:#a12a2a}</style></head><body><header class="top"><b>SPS CRM · Approvals</b> · <a href="dashboard.php">Dashboard</a></header><main class="wrap"><div class="card"><h1>Approval Queue</h1><table class="table"><tr><th>Client</th><th>Entity</th><th>Level</th><th>Status</th><th>Decision</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['client_name']?:'—')?></td><td><?=e($r['entity_type'].' #'.($r['entity_id']??'—'))?></td><td><?=e($r['level'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" name="decision" value="approved">Approve</button> <button class="btn reject" name="decision" value="rejected">Reject</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></main></body></html>
